def classify_region(lat, lon):
    fallback = {'name': 'Unclassified', 'thesis': 'Global macro exposure - broad reinsurance ETF (KIE)'}
    if lat is None or lon is None:
        return fallback
    for zi in range(len(ECONOMIC_ZONES)):
        zone = ECONOMIC_ZONES[zi]
        if lat >= zone['lat_min'] and lat <= zone['lat_max'] and lon >= zone['lon_min'] and lon <= zone['lon_max']:
            return {'name': zone['name'], 'thesis': zone['thesis']}
    return fallback

def severity_from_mag(mag, pager, sig):
    if pager == 'red' or pager == 'orange':
        return 'CRITICAL'
    if mag is not None and mag >= 7.0:
        return 'CRITICAL'
    if mag is not None and mag >= 6.0:
        return 'HIGH'
    if pager == 'yellow':
        return 'HIGH'
    if sig is not None and sig >= 600:
        return 'HIGH'
    if mag is not None and mag >= 5.0:
        return 'MODERATE'
    return 'LOW'

